{-| @Backend.Runtime.Host.Compress — bounded gzip and bare-stream conversion through the system's zlib, as `Pudu.Eval.Compress` answers it. -}
module Pudu.Backend.Runtime.Host.Compress (hostCompressParts, compressLibraryMarker) where

import Data.Text (Text)

{-| The line whose presence in a program's C says the program links zlib. -}
compressLibraryMarker :: Text
compressLibraryMarker = "#include <zlib.h>"

{-| Each part: its name, the parts it needs, and its lines. -}
hostCompressParts :: [(Text, [Text], [Text])]
hostCompressParts =
  [ ("host_zlib", ["host_optional", "host_done", "host_fail", "host_grow", "kernel_signed", "kernel_fresh", "bytes_wrap", "memory_failure"],
      [ compressLibraryMarker
      , "/* What a conversion has produced so far. */"
      , "typedef struct { unsigned char *bytes; size_t held, room; } pudu_host_packed;"
      , "PUDU_OPTIONAL static inline void pudu_host_packed_room(pudu_host_packed *out, size_t more) {"
      , "  if (out->room - out->held >= more) return;"
      , "  while (out->room - out->held < more) out->room = out->room < 4096 ? 4096 : out->room * 2;"
      , "  out->bytes = pudu_host_grow(out->bytes, out->room);"
      , "}"
      , "PUDU_OPTIONAL static inline pudu_box *pudu_host_packed_bytes(pudu_host_packed *out) {"
      , "  unsigned char *bytes;"
      , "  pudu_text fresh = pudu_kernel_fresh(out->held, &bytes);"
      , "  if (out->held != 0) memcpy(bytes, out->bytes, out->held);"
      , "  free(out->bytes);"
      , "  pudu_host_done(0);"
      , "  return pudu_bytes_wrap(fresh);"
      , "}"
      ])
  , ("host_deflate", ["host_zlib"],
      [ "/* Mode 0 writes the gzip wrapper, mode 1 the bare stream. The chunk size"
      , "   sizes buffers only and leaves the bytes as they are. */"
      , "static pudu_box *pudu_host_deflate(pudu_box *input, pudu_int level, pudu_int chunk, int mode) {"
      , "  pudu_text given = input->fields[0].text;"
      , "  int64_t wanted = pudu_kernel_signed(level.bits);"
      , "  pudu_host_packed out = {NULL, 0, 0};"
      , "  z_stream stream;"
      , "  size_t fed = 0;"
      , "  int status = Z_OK;"
      , "  (void)chunk;"
      , "  if (wanted < 0 || wanted > 9) { pudu_host_fail(\"invalid compression level\"); return NULL; }"
      , "  memset(&stream, 0, sizeof stream);"
      , "  if (deflateInit2(&stream, (int)wanted, Z_DEFLATED, mode == 0 ? 31 : -15, 8, Z_DEFAULT_STRATEGY) != Z_OK) pudu_memory_failure();"
      , "  while (status != Z_STREAM_END) {"
      , "    size_t piece = given.length - fed > 1073741824u ? 1073741824u : given.length - fed;"
      , "    stream.next_in = (Bytef *)(uintptr_t)(given.bytes + fed);"
      , "    stream.avail_in = (uInt)piece;"
      , "    fed += piece;"
      , "    do {"
      , "      pudu_host_packed_room(&out, 32768);"
      , "      stream.next_out = out.bytes + out.held;"
      , "      stream.avail_out = 32768;"
      , "      status = deflate(&stream, fed == given.length ? Z_FINISH : Z_NO_FLUSH);"
      , "      out.held += 32768 - stream.avail_out;"
      , "    } while (stream.avail_out == 0 && status != Z_STREAM_END);"
      , "  }"
      , "  (void)deflateEnd(&stream);"
      , "  return pudu_host_packed_bytes(&out);"
      , "}"
      ])
  , ("host_inflate", ["host_zlib"],
      [ "/* Mode 0 reads one gzip member, mode 1 one bare stream, up to the limit. */"
      , "static pudu_box *pudu_host_inflate(pudu_box *input, pudu_int limit, int mode) {"
      , "  pudu_text given = input->fields[0].text;"
      , "  int64_t allowed = pudu_kernel_signed(limit.bits);"
      , "  pudu_host_packed out = {NULL, 0, 0};"
      , "  z_stream stream;"
      , "  size_t fed = 0;"
      , "  int status = Z_OK;"
      , "  const char *refusal = NULL;"
      , "  char words[256];"
      , "  if (allowed < 0) { pudu_host_fail(\"negative decompression limit\"); return NULL; }"
      , "  memset(&stream, 0, sizeof stream);"
      , "  if (inflateInit2(&stream, mode == 0 ? 31 : -15) != Z_OK) pudu_memory_failure();"
      , "  while (refusal == NULL && status != Z_STREAM_END) {"
      , "    size_t piece;"
      , "    if (stream.avail_in == 0) {"
      , "      if (fed == given.length) { refusal = \"Codec.Compression.Zlib: premature end of compressed data stream\"; break; }"
      , "      piece = given.length - fed > 32768 ? 32768 : given.length - fed;"
      , "      stream.next_in = (Bytef *)(uintptr_t)(given.bytes + fed);"
      , "      stream.avail_in = (uInt)piece;"
      , "      fed += piece;"
      , "    }"
      , "    pudu_host_packed_room(&out, 32768);"
      , "    stream.next_out = out.bytes + out.held;"
      , "    stream.avail_out = 32768;"
      , "    status = inflate(&stream, Z_NO_FLUSH);"
      , "    if (status == Z_NEED_DICT) refusal = \"Codec.Compression.Zlib: compressed data stream requires custom dictionary\";"
      , "    else if (status == Z_MEM_ERROR) pudu_memory_failure();"
      , "    else if (status == Z_DATA_ERROR || status == Z_STREAM_ERROR) {"
      , "      (void)snprintf(words, sizeof words, \"Codec.Compression.Zlib: compressed data stream format error (%s)\", stream.msg != NULL ? stream.msg : \"\");"
      , "      refusal = words;"
      , "    } else {"
      , "      size_t took = 32768 - stream.avail_out;"
      , "      if ((uint64_t)took > (uint64_t)allowed - (uint64_t)out.held) refusal = \"decompressed output limit exceeded\";"
      , "      else out.held += took;"
      , "    }"
      , "  }"
      , "  if (refusal == NULL && (stream.avail_in != 0 || fed != given.length)) refusal = \"trailing bytes after gzip member\";"
      , "  (void)inflateEnd(&stream);"
      , "  if (refusal != NULL) { free(out.bytes); pudu_host_fail(refusal); return NULL; }"
      , "  return pudu_host_packed_bytes(&out);"
      , "}"
      ])
  ]
